source /root/miniconda3/etc/profile.d/conda.sh && conda activate base && python -c "
import json
for gen in [0,1,2]:
    for seed in [42,137]:
        fn = f'/root/prism_collapse_mixing/results/signals_gen{gen}_seed{seed}.json'
        with open(fn) as f:
            d = json.load(f)
        print(f'gen{gen}_seed{seed} keys: {list(d.keys())}')
        if 'corpus' in d:
            print(f'  corpus: {d[\"corpus\"]}')
        if 'correlation' in d:
            print(f'  correlation: {d[\"correlation\"]}')
        if 'distinct' in d:
            print(f'  distinct: {d[\"distinct\"]}')
        # check all top-level keys that aren't 'samples' or 'aggregated'
        for k in d:
            if k not in ('samples', 'aggregated'):
                print(f'  [{k}]: {json.dumps(d[k])[:200]}')
"

